    {
        var userId = GetUserId();
        var experiments = _experimentService.GetUserExperiments(userId);
        return Ok(experiments);
    }

    [HttpGet("{id}")]
    public IActionResult GetById(int id)
    {
        var userId = GetUserId();
        var experiment = _experimentService.GetExperiment(id, userId);

