    {
        var userId = GetUserId();
        _antiforgery.ValidateRequest(HttpContext);
        var experiment = _experimentService.CreateExperiment(
            userId,
            request.Name,
            request.Description,
            request.Hypothesis
        );
        return CreatedAtAction(nameof(GetById), new { id = experiment.Id }, experiment);
    }

