        [id, user.id, input.title, input.url, input.order, input.published || false, new Date().toISOString()]
      );
      return { id, userId: user.id, title: input.title, url: input.url, order: input.order, published: input.published || false, createdAt: new Date().toISOString() };
    },
    updateLink: async (parent, { input }, { pool, user }) => {
      if (!user) throw new Error('Unauthorized');
      const check = await pool.query('SELECT * FROM links WHERE id = $1', [input.id]);
      if (check.rows[0].user_id !== user.id && user.role !== 'admin') throw new Error('Unauthorized');
      let updateFields = [];
      let params = [];
      if (input.title) { updateFields.push(`title = $${params.length + 1}`); params.push(input.title); }
      if (input.url) { updateFields.push(`url = $${params.length + 1}`); params.push(input.url); }
      if (input.order !== undefined) { updateFields.push(`order = $${params.length + 1}`); params.push(input.order); }
      if (input.published !== undefined) { updateFields.push(`published = $${params.length + 1}`); params.push(input.published); }
      if (updateFields.length === 0) throw new Error('Nothing to update');
      params.push(input.id);
      await pool.query(`UPDATE links SET ${updateFields.join(', ')} WHERE id = $${params.length}`, params);
      const result = await pool.query('SELECT * FROM links WHERE id = $1', [input.id]);
      return result.rows[0];
    },
    deleteLink: async (parent, { id }, { pool, user }) => {
      if (!user) throw new Error('Unauthorized');
      const check = await pool.query('SELECT * FROM links WHERE id = $1', [id]);
      if (check.rows[0].user_id !== user.id && user.role !== 'admin') throw new Error('Unauthorized');
      await pool.query('DELETE FROM links WHERE id = $1', [id]);
      return true;
    },
    updateProfile: async (parent, { bio }, { pool, user }) => {
      if (!user) throw new Error('Unauthorized');
      await pool.query('UPDATE users SET bio = $1 WHERE id = $2', [bio, user.id]);
      const result = await pool.query('SELECT * FROM users WHERE id = $1', [user.id]);
      delete result.rows[0].password;
      return result.rows[0];
    },
    adminUpdateUser: async (parent, { input }, { pool, user }) => {
      if (!user || user.role !== 'admin') throw new Error('Unauthorized');
      await pool.query('UPDATE users SET role = $1 WHERE id = $2', [input.role, input.id]);
      const result = await pool.query('SELECT id, username, email, role, bio, created_at FROM users WHERE id = $1', [input.id]);
      return result.rows[0];
    },
  },
  User: {
    createdAt: (user) => user.created_at,
  },
  Link: {
    createdAt: (link) => link.created_at,
  },
};

from starlette.applications import Starlette
from starlette.responses import JSONResponse
from starlette.requests import Request
from starlette.routing import Route
from starlette.middleware.cors import CORSMiddleware
from starlette.responses import FileResponse

from .database import create_tables, SessionLocal
from .crud import (
    create_user, authenticate_user, get_expenses, create_expense,
    get_expense, delete_expense
)
from .schemas import UserCreate, ExpenseCreate, Expense
from .auth import create_access_token, verify_token

create_tables()

async def register(request: Request):
    db = SessionLocal()
    try:
        data = await request.json()
        user_create = UserCreate(username=data["username"], password=data["password"])
        if get_user_by_username(db, user_create.username):
            return JSONResponse({"detail": "Username already exists"}, status_code=409)
        user = create_user(db=db, user=user_create)
        return JSONResponse({"msg": "user created", "user_id": user.id})
    finally:
        db.close()

async def login(request: Request):
    db = SessionLocal()
    try:
        data = await request.json()
        user = authenticate_user(db, data["username"], data["password"])
        if not user:
            return JSONResponse({"detail": "Invalid credentials"}, status_code=401)
        access_token = create_access_token(user.username, user.id)
        return JSONResponse({"access_token": access_token, "token_type": "bearer"})
    finally:
        db.close()

async def expenses_list(request: Request):
    db = SessionLocal()
    try:
        user_id = verify_token(request.headers.get("authorization", ""))
        if not user_id:
            return JSONResponse({"detail": "Not authenticated"}, status_code=401)
        expenses = get_expenses(db, user_id)
        return JSONResponse([Expense.from_orm(e).dict() for e in expenses])
    finally:
        db.close()

async def create_expense_route(request: Request):
    db = SessionLocal()
    try:
        user_id = verify_token(request.headers.get("authorization", ""))
        if not user_id:
            return JSONResponse({"detail": "Not authenticated"}, status_code=401)
        data = await request.json()
        expense = ExpenseCreate(**data)
        new_exp = create_expense(db, expense, user_id)
        return JSONResponse(Expense.from_orm(new_exp).dict(), status_code=201)
    finally:
        db.close()

async def get_expense_route(request: Request):
    db = SessionLocal()
    try:
        user_id = verify_token(request.headers.get("authorization", ""))
        if not user_id:
            return JSONResponse({"detail": "Not authenticated"}, status_code=401)
        expense_id = int(request.path_params["expense_id"])
        exp = get_expense(db, expense_id, user_id)
        if not exp:
            return JSONResponse({"detail": "Expense not found"}, status_code=404)
        return JSONResponse(Expense.from_orm(exp).dict())
    finally:
        db.close()

async def delete_expense_route(request: Request):
    db = SessionLocal()
    try:
        user_id = verify_token(request.headers.get("authorization", ""))
        if not user_id:
            return JSONResponse({"detail": "Not authenticated"}, status_code=401)
        expense_id = int(request.path_params["expense_id"])
        if delete_expense(db, expense_id, user_id):
            return JSONResponse({"msg": "Expense deleted"})
        return JSONResponse({"detail": "Expense not found"}, status_code=404)
    finally:
        db.close()

async def swagger_spec(request: Request):
    return FileResponse("openapi.yaml", media_type="application/yaml")

routes = [
    Route("/auth/register", register, methods=["POST"]),
    Route("/auth/login", login, methods=["POST"]),
    Route("/expenses", expenses_list, methods=["GET"]),
    Route("/expenses", create_expense_route, methods=["POST"]),
    Route("/expenses/{expense_id}", get_expense_route, methods=["GET"]),
    Route("/expenses/{expense_id}", delete_expense_route, methods=["DELETE"]),
    Route("/swagger", swagger_spec, methods=["GET"]),
]

app = Starlette(routes=routes)
app.add_middleware(
    CORSMiddleware,
    allow_origins=["http://localhost", "http://localhost:8080"],  # Replace with specific origins
    allow_credentials=True,
    allow_methods=["GET", "POST", "PUT", "DELETE"],
    allow_headers=["*"],
)
